 [("משך הנסיעה", "בערך 3–4 שעות; אוטובוסים עם הרבה עצירות לוקחים יותר"), ("לימוזינה או אוטובוס", "לימוזינות מהירות יותר ובדרך כלל ממלון למלון; אוטובוסים גדולים זולים יותר ויוצאים מתחנות וממשרדים"), ("מעבר קאן לה", "כביש הררי ארוך ומפותל — מי שסובל מבחילה בנסיעה, כדאי לקחת כדור מראש"), ("הזמנה", "בסופי שבוע ובחגים הזמינו יום מראש; בקשו הורדה במלון")],
